fn check_lamp_arrangement(r: i8, g: i8, b: i8) -> bool {
    // Promote to i32 so that r+g+b cannot overflow an i8.
    let total = r as i32 + g as i32 + b as i32;
    // Compute the maximum of the three counts, also as i32.
    let max = r.max(g).max(b) as i32;
    // Check the feasibility condition: 2 * max <= total + 1
    2 * max <= total + 1
}

